JS="""// DATASET. FEES MARKED null ARE UNVERIFIED. Fill each from parivahan.gov.in before launch.
const KT=%s;
const $=s=>document.querySelector(s),ic=(p)=>`<svg class="i" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
const feeTxt=f=>(f.official==null?'Official fee: to be confirmed on parivahan.gov.in':`Official fee: \u20b9${f.official}`)+(f.reported?` (some applicants report ~\u20b9${f.reported} - amounts may vary and change without notice)`:' (amounts may change without notice)');
function tick(root){root.querySelectorAll('input[data-k]').forEach(b=>{try{b.checked=localStorage.getItem(b.dataset.k)==='1'}catch(e){}b.onchange=()=>{try{localStorage.setItem(b.dataset.k,b.checked?'1':'0')}catch(e){}prog(root)}});prog(root)}
function prog(r){const a=[...r.querySelectorAll('input[data-k]')],n=a.filter(x=>x.checked).length,p=r.querySelector('.prog');if(p)p.textContent=n+' of '+a.length+' documents ready'}
function docHtml(sid,i,x){const d=KT.docdetail[x];if(!d)return `<label class="chk"><input type="checkbox" data-k="kt:${sid}:${i}"> ${x}</label>`;return `<div class="doc"><label class="chk"><input type="checkbox" data-k="kt:${sid}:${i}"> ${x}</label><button type="button" class="docbtn" aria-expanded="false" aria-label="Show accepted documents">\u25be</button><div class="docd" hidden>${d}</div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('.docbtn');if(!b)return;const d=b.parentElement.querySelector('.docd'),open=d.hidden;d.hidden=!open;b.setAttribute('aria-expanded',String(open));b.textContent=open?'\u25b4':'\u25be'});
function render(sid,did){const s=KT.services[sid],d=KT.districts[did],o=$('#out');if(!s||!d){o.innerHTML='<p class="note">Pick a service and a district first.</p>';return}
const tot=s.fees.every(f=>f.official!=null)?'\u20b9'+s.fees.reduce((a,f)=>a+f.official,0):'To be confirmed';
o.innerHTML=`<div class="grid g2"><div class="card" id="cl"><span class="badge">${s.online}</span><h3>${s.name}: your checklist</h3><p class="prog"></p>
${s.docs.map((x,i)=>docHtml(sid,i,x)).join('')}
<p class="wm">keralamtransport.com - verify on parivahan.gov.in</p></div>
<div class="card"><h3>Steps</h3><ol class="steps">${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${s.note?`<p class="note">${s.note}</p>`:''}<p class="note">Time estimate: ${s.time||'to be confirmed; it depends on your RTO and slot availability'}.</p></div></div>
<div class="grid g2"><div class="card"><h3>Fees</h3><table>${s.fees.map(f=>`<tr><td>${f.l}</td><td>${feeTxt(f)}</td></tr>`).join('')}<tr><th>Total</th><th>${tot}</th></tr></table><p class="note">Any gap between official and reported amounts is usually a service charge or an optional add-on. Always ask for a receipt.</p></div>
<div class="card"><h3>${d.district} RTO</h3><p><strong>${d.code}</strong> - ${d.town}</p><p class="note">Address and hours: confirm on the office page before you travel.</p><a class="btn" href="/rto-offices/${d.code.toLowerCase()}.html">Office details</a></div></div>
<div class="row"><a class="btn amb" href="${KT.link}" target="_blank" rel="noopener">Start on Parivahan</a><button class="btn ghost" id="shot">Take Screenshot</button></div>`;
tick(o);$('#shot').onclick=()=>{const l=document.createElement('script');const go=()=>htmlToImage.toPng($('#cl'),{backgroundColor:'#F6F1E4'}).then(u=>{const a=document.createElement('a');a.href=u;a.download='checklist-'+sid+'.png';a.click()});if(window.htmlToImage)go();else{l.src='https://cdn.jsdelivr.net/npm/html-to-image@1.11.11/dist/html-to-image.js';l.onload=go;document.head.appendChild(l)}}}
function init(){const f=$('#finder');if(!f)return;const sv=f.querySelector('[name=s]'),dv=f.querySelector('[name=d]');
f.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{f.querySelectorAll('.chip').forEach(x=>x.setAttribute('aria-pressed','false'));c.setAttribute('aria-pressed','true');sv.value=c.dataset.s});
f.onsubmit=e=>{e.preventDefault();render(sv.value,dv.value);$('#out').scrollIntoView({behavior:'smooth'})};
const bar=document.querySelector('.bar a');if(bar)bar.onclick=e=>{e.preventDefault();if(f.requestSubmit)f.requestSubmit();else f.dispatchEvent(new Event('submit',{cancelable:true}))};
const p=f.dataset.s;if(p){f.querySelectorAll('.chip').forEach(c=>c.setAttribute('aria-pressed',c.dataset.s===p))}
document.querySelectorAll('.static').forEach(tick)}
document.addEventListener('DOMContentLoaded',init);"""%json.dumps(data)
CSS=""":root{color-scheme:only light;--t:#0C5B4C;--a:#E8962E;--sand:#F6F1E4;--ink:#1C2B26;--line:#DDD5BF}*{box-sizing:border-box}body{margin:0;background:var(--sand);color:var(--ink);font:16px/1.6 'Plus Jakarta Sans',sans-serif;padding-bottom:64px}
h1,h2,h3{font-family:Fraunces,serif;line-height:1.2;margin:.2em 0 .5em}h1{font-size:2rem}h2{font-size:1.5rem}a{color:var(--t)}.w{max-width:1040px;margin:auto;padding:0 18px}
header{background:#fff;border-bottom:1px solid var(--line)}header .w{display:flex;justify-content:space-between;align-items:center;padding:12px 18px;flex-wrap:wrap;gap:8px}.logo{font:700 1.2rem Fraunces,serif;text-decoration:none;display:flex;gap:8px;align-items:center}nav a{margin-right:14px;font-size:.9rem;text-decoration:none}
.hero{position:relative;overflow:hidden;background:var(--t);color:#fff;padding:36px 0 40px}.hero:before{content:"കേരളം";position:absolute;right:-10px;top:-10px;font-size:9rem;opacity:.07;line-height:1;pointer-events:none}.hero .w{position:relative}
.sec{padding:36px 0}.c{text-align:center}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px}.grid{display:grid;gap:14px;margin:14px 0}.g2{grid-template-columns:1fr}.g3,.g4{grid-template-columns:1fr}
@media(min-width:700px){.g2{grid-template-columns:1fr 1fr}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr)}.s2{grid-template-columns:2fr 1fr}body{padding-bottom:0}.bar{display:none}h1{font-size:2.6rem}}
.btn{display:inline-block;border:0;border-radius:8px;padding:12px 18px;background:var(--t);color:#fff;font:600 1rem inherit;font-family:inherit;text-decoration:none;cursor:pointer}.amb{background:var(--a);color:var(--ink)}.ghost{background:#fff;color:var(--t);border:1px solid var(--t)}
.fm{background:#fff;color:var(--ink);border-radius:16px;padding:16px;margin-top:18px}.fm h3{font-size:1rem;font-family:'Plus Jakarta Sans';margin:.8em 0 .4em}.chip{border:1px solid var(--line);background:var(--sand);border-radius:8px;padding:8px 12px;margin:0 6px 6px 0;cursor:pointer;font:inherit}.chip[aria-pressed=true]{background:var(--t);color:#fff;border-color:var(--t)}
select{width:100%;padding:11px;border-radius:8px;border:1px solid var(--line);font:inherit;margin-bottom:12px}.strip{background:#fff;border-bottom:1px solid var(--line);padding:12px 0;font-size:.9rem}.strip .w{display:flex;gap:18px;flex-wrap:wrap;justify-content:center}
.i{width:18px;height:18px;vertical-align:-3px;margin-right:6px}.badge{display:inline-block;background:#E4EFEA;color:var(--t);border-radius:8px;padding:2px 10px;font-size:.8rem;font-weight:600}.badge.ex{background:#FBE9CF}
.chk{display:block;padding:6px 0;border-bottom:1px dashed var(--line)}.chk input{margin-right:8px;accent-color:var(--t)}
.doc{position:relative;border-bottom:1px dashed var(--line)}.doc .chk{border:0;padding-right:38px}.docbtn{position:absolute;right:2px;top:6px;width:28px;height:28px;border:1px solid var(--line);background:var(--sand);border-radius:6px;cursor:pointer;font:inherit;color:var(--t);line-height:1}.docd{font-size:.88rem;opacity:.85;padding:0 0 10px 26px}.steps li{margin-bottom:8px}table{width:100%;border-collapse:collapse;font-size:.92rem}td,th{text-align:left;padding:8px 4px;border-bottom:1px solid var(--line);vertical-align:top}.note,.wm{font-size:.85rem;opacity:.75}.row{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}
details{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin-bottom:8px}summary{font-weight:600;cursor:pointer}footer{background:var(--ink);color:#dfe8e3;padding:28px 0;font-size:.9rem}footer a{color:#fff;margin-right:12px}
.bar{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid var(--line);padding:10px 14px;z-index:9}.bar .btn{display:block;text-align:center}.small a{text-decoration:none}"""
IC={"c":'<path d="M20 6 9 17l-5-5"/>',"m":'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',"f":'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6"/>'}
def ic(k):return f'<svg class="i" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{IC[k]}</svg>'
def docitem(kp,i,x):
    d=DD.get(x)
    if d:return f'<div class="doc"><label class="chk"><input type="checkbox" data-k="{kp}:{i}"> {x}</label><button type="button" class="docbtn" aria-expanded="false" aria-label="Show accepted documents">\u25be</button><div class="docd" hidden>{d}</div></div>'
    return f'<label class="chk"><input type="checkbox" data-k="{kp}:{i}"> {x}</label>'
FAV='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="7" fill="#0C5B4C"/><rect x="5" y="10" width="22" height="12" rx="2.5" fill="#ffffff"/><path d="M5 12.5a2.5 2.5 0 0 1 2.5-2.5h17A2.5 2.5 0 0 1 27 12.5V14H5z" fill="#1E5AA8"/><text x="16" y="20.6" font-family="Arial,sans-serif" font-size="6.5" font-weight="bold" fill="#000000" text-anchor="middle">KL 07</text></svg>'
def page(path,title,desc,body,ld=""):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="only light"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="https://keralamtransport.com{path}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:url" content="https://keralamtransport.com{path}"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@600;700&family=Plus+Jakarta+Sans:wght@400;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="/style.css">{CF_BEACON}{ld}</head><body><header><div class="w"><a class="logo" href="/"><img src="/favicon.svg" width="26" height="26" alt="">Keralam Transport</a><nav><a href="/finder.html">Finder</a><a href="/#services">Services</a><a href="/#offices">RTO offices</a><a href="/blog/index.html">Blog</a><a href="/about.html">About</a></nav></div></header>{body}<footer><div class="w"><p><a href="/about.html">About</a><a href="/contact.html">Contact</a><a href="/privacy.html">Privacy</a><a href="/disclaimer.html">Disclaimer and Terms</a></p><p>Not affiliated with Kerala MVD - verify on <a href="https://parivahan.gov.in/" rel="noopener">parivahan.gov.in</a>. Fees and rules change without notice.</p></div></footer><div class="bar"><a class="btn amb" href="/finder.html">Show my process</a></div><script src="/finder.js" defer></script></body></html>'''
def form(pre=None):
    ch="".join(f'<h3>{g}</h3>'+"".join(f'<button type="button" class="chip" data-s="{s[0]}" aria-pressed="false">{s[1]}</button>' for s in S if s[2]==g) for g in ["Licence","Vehicle","Other"])
    opts="".join(f'<option value="{i}">{d[1]} ({d[0]})</option>' for i,d in enumerate(D))
    return f'<form id="finder" class="fm" data-s="{pre or ""}"><input type="hidden" name="s" value="{pre or ""}">{ch}<h3>Your district</h3><select name="d">{opts}</select><button class="btn amb" type="submit">Show my process</button></form><div id="out"></div>'
def faq(qs):return "".join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in qs),'<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in qs]})+'</script>'
F=[("Are the fees on this site final?","No. Each fee is shown as the official amount from Parivahan, and amounts change without notice. Where a fee is not yet confirmed we say so instead of guessing."),("Is Keralam Transport a government site?","No. It is an independent guide and is not affiliated with Kerala MVD. Every application is filed on parivahan.gov.in."),("How hard is the Kerala driving test?","Kerala's driving test is India's toughest by reputation, and the ground test rewards practice. Book enough lessons before your slot."),("Do I need to visit the RTO?","Many steps are online, but some services still need an in-person visit for a test or verification. Each service page shows an online or offline badge.")]
def w(p,c):
    os.makedirs(os.path.dirname("."+p) or ".",exist_ok=True);open("."+p,"w").write(c)
w("/favicon.svg",FAV);w("/finder.js",JS);w("/style.css",CSS)
